def transform(grid):
    # Extract the yellow mask, green components, and two solid color fields.
    ys=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==4]
    r0,r1=min(r for r,c in ys),max(r for r,c in ys)
    c0,c1=min(c for r,c in ys),max(c for r,c in ys)
    mask=[[grid[r][c]==4 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    gs={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3}
    comps=[]
    while gs:
        seed=gs.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in gs: gs.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    colors=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v not in (0,1,3,4): colors.append(v)
    a,b=sorted(set(colors),key=lambda x:colors.index(x))
    # Components arranged left-to-right give horizontal copies; otherwise vertical.
    horizontal=(demo2 is not None and len({r for comp in comps for r,c in comp}) < len({c for comp in comps for r,c in comp}))
    if horizontal:
        comps.sort(key=lambda comp:min(c for r,c in comp))
        out=[]
        for row in mask:
            line=[]
            for i in range(len(comps)):
                if i: line.append(b)
                line += [a if x else b for x in row]
            out.append(line)
    else:
        comps.sort(key=lambda comp:min(r for r,c in comp))
        out=[]
        for i in range(len(comps)):
            if i: out.append([b]*len(mask[0]))
            out += [[a if x else b for x in row] for row in mask]
    return out
