def transform(grid):
    from collections import Counter
    horizontal=len(grid[0])>len(grid)
    ys=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==4]
    r0,r1=min(r for r,c in ys),max(r for r,c in ys); c0,c1=min(c for r,c in ys),max(c for r,c in ys)
    mask=[[grid[r][c]==4 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    if horizontal:
        last_sep=max(c for c in range(len(grid[0])) if all(grid[r][c]==1 for r in range(len(grid))))
        gs={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3 and c<last_sep}
    else:
        last_sep=max(r for r in range(len(grid)) if all(v==1 for v in grid[r]))
        gs={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3 and r<last_sep}
    comps=[]
    while gs:
        seed=gs.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in gs: gs.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    counts=Counter(v for row in grid for v in row if v not in (0,1,4))
    b=grid[-1][-1] if not horizontal else grid[0][-1]
    a=next(v for v,n in counts.most_common() if v!=b)
    if horizontal:
        comps.sort(key=lambda comp:min(c for r,c in comp)); out=[]
        for row in mask:
            line=[]
            for i in range(len(comps)):
                if i: line.append(b)
                line += [a if x else b for x in row]
            out.append(line)
    else:
        comps.sort(key=lambda comp:min(r for r,c in comp)); out=[]
        for i in range(len(comps)):
            if i: out.append([b]*len(mask[0]))
            out += [[a if x else b for x in row] for row in mask]
    return out
